def words_string(s):
    import re
    # Split the string by commas or spaces using regex
    return re.split(r'[ ,]+', s.strip())

def minPath(grid, k):
    from collections import deque
    N = len(grid)
    # Find the starting point with the minimum value, which is guaranteed to be 1
    start = None
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 1:
                start = (i, j)
                break
        if start:
            break
    path = []
    current = start
    for _ in range(k):
        path.append(grid[current[0]][current[1]])
        # Get all valid neighbors
        neighbors = []
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = current[0] + di, current[1] + dj
            if 0 <= ni < N and 0 <= nj < N:
                neighbors.append((grid[ni][nj], (ni, nj)))
        # Move to the neighbor with the smallest value
        if neighbors:
            neighbors.sort()  # Sort by value, then by position
            current = neighbors[0][1]
    return path

def sum_squares(lst):
    total = 0
    for index, value in enumerate(lst):
        if index % 3 == 0:
            total += value ** 2
        elif index % 4 == 0:
            total += value ** 3
        else:
            total += value
    return total

def order_by_points(nums):
    def points(n):
        if n >= 0:
            return sum(int(digit) for digit in str(n))
        else:
            digits = str(n)[1:]
            return -int(digits[0]) + sum(int(digit) for digit in digits[1:])
    return sorted(nums, key=points)

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise."""
    if n <= 1:
        return y
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return y
    return x

def even_odd_count(num):
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    if text == '':
        return None
    return hashlib.md5(text.encode('utf-8')).hexdigest()
